/// Every route of the app. Feature agents do not edit this file: each route
/// already points at the screen widget in its own file under lib/features/.
///
/// Navigation rules:
/// * Tabs (`/`, `/charts`, `/reports`, `/settings`) live in the shell with
///   the bottom bar. Switch tabs with `context.go(Routes.charts)`.
/// * Every other route opens ABOVE the shell (no bottom bar). Open them
///   with `context.push(...)` so Back (and the system back gesture) returns
///   to where the user was. Close with `context.pop()` (optionally with a
///   result).
library;

import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';

import 'features/add/add_screen.dart';
import 'features/calendar/calendar_screen.dart';
import 'features/categories/categories_screen.dart';
import 'features/categories/category_form_screen.dart';
import 'features/charts/category_screen.dart';
import 'features/charts/charts_screen.dart';
import 'features/data/export_screen.dart';
import 'features/data/import_columns_screen.dart';
import 'features/data/import_review_screen.dart';
import 'features/data/import_screen.dart';
import 'features/expense/details_screen.dart';
import 'features/expense/photo_screen.dart';
import 'features/home/home_screen.dart';
import 'features/pockets/pocket_form_screen.dart';
import 'features/pockets/pockets_screen.dart';
import 'features/reports/reports_screen.dart';
import 'features/settings/settings_screen.dart';
import 'widgets/app_shell.dart';

/// Paths, and builders for paths with parameters.
abstract final class Routes {
  // Tabs.
  static const String home = '/';
  static const String charts = '/charts';
  static const String reports = '/reports';
  static const String settings = '/settings';

  /// Add expense, optionally on a given day (Calendar's "Add expense on").
  static String add({int? day}) => day == null ? '/add' : '/add?day=$day';

  /// Expense details.
  static String expense(int id) => '/expense/$id';

  /// Edit expense (the Add expense screen, prefilled).
  static String editExpense(int id) => '/expense/$id/edit';

  /// Full-screen receipt photo of an expense.
  static String expensePhoto(int id) => '/expense/$id/photo';

  /// Calendar, optionally opened on the month of [day].
  static String calendar({int? day}) =>
      day == null ? '/calendar' : '/calendar?day=$day';

  /// Category drill-down for a day range (inclusive day numbers).
  static String category(int id, {int? from, int? to}) {
    final q = [if (from != null) 'from=$from', if (to != null) 'to=$to'];
    return q.isEmpty ? '/category/$id' : '/category/$id?${q.join('&')}';
  }

  static const String categories = '/settings/categories';
  static const String newCategory = '/settings/categories/new';
  static String editCategory(int id) => '/settings/categories/$id';

  static const String pockets = '/pockets';
  static const String newPocket = '/pockets/new';
  static String editPocket(int id) => '/pockets/$id';

  static const String export = '/settings/export';
  static const String importStart = '/settings/import';
  static const String importColumns = '/settings/import/columns';
  static const String importReview = '/settings/import/review';
}

int _id(GoRouterState s) => int.tryParse(s.pathParameters['id'] ?? '') ?? -1;

int? _query(GoRouterState s, String key) =>
    int.tryParse(s.uri.queryParameters[key] ?? '');

/// Builds the router. Tests can start elsewhere with [initialLocation].
GoRouter buildRouter({String initialLocation = Routes.home}) {
  final rootKey = GlobalKey<NavigatorState>(debugLabel: 'root');
  GoRoute top(String path, GoRouterWidgetBuilder builder) => GoRoute(
        path: path,
        parentNavigatorKey: rootKey,
        builder: builder,
      );

  return GoRouter(
    navigatorKey: rootKey,
    initialLocation: initialLocation,
    routes: [
      StatefulShellRoute.indexedStack(
        builder: (context, state, shell) => AppShell(
          navigationShell: shell,
          onAdd: () => context.push(Routes.add()),
        ),
        branches: [
          StatefulShellBranch(
            routes: [
              GoRoute(
                path: Routes.home,
                builder: (_, _) => const HomeScreen(),
              ),
            ],
          ),
          StatefulShellBranch(
            routes: [
              GoRoute(
                path: Routes.charts,
                builder: (_, _) => const ChartsScreen(),
              ),
            ],
          ),
          StatefulShellBranch(
            routes: [
              GoRoute(
                path: Routes.reports,
                builder: (_, _) => const ReportsScreen(),
              ),
            ],
          ),
          StatefulShellBranch(
            routes: [
              GoRoute(
                path: Routes.settings,
                builder: (_, _) => const SettingsScreen(),
              ),
            ],
          ),
        ],
      ),
      // Above the shell. Specific paths come before parameter paths.
      top('/add', (_, s) => AddScreen(day: _query(s, 'day'))),
      top('/expense/:id/edit', (_, s) => AddScreen(expenseId: _id(s))),
      top('/expense/:id/photo', (_, s) => PhotoScreen(expenseId: _id(s))),
      top('/expense/:id', (_, s) => ExpenseDetailsScreen(expenseId: _id(s))),
      top('/calendar', (_, s) => CalendarScreen(day: _query(s, 'day'))),
      top(
        '/category/:id',
        (_, s) => CategoryScreen(
          categoryId: _id(s),
          from: _query(s, 'from'),
          to: _query(s, 'to'),
        ),
      ),
      top(Routes.categories, (_, _) => const CategoriesScreen()),
      top(Routes.newCategory, (_, _) => const CategoryFormScreen()),
      top(
        '/settings/categories/:id',
        (_, s) => CategoryFormScreen(categoryId: _id(s)),
      ),
      top(Routes.pockets, (_, _) => const PocketsScreen()),
      top(Routes.newPocket, (_, _) => const PocketFormScreen()),
      top('/pockets/:id', (_, s) => PocketFormScreen(pocketId: _id(s))),
      top(Routes.export, (_, _) => const ExportScreen()),
      top(Routes.importStart, (_, _) => const ImportScreen()),
      top(Routes.importColumns, (_, _) => const ImportColumnsScreen()),
      top(Routes.importReview, (_, _) => const ImportReviewScreen()),
    ],
  );
}

/// The app's router. Override in tests to start on another route:
/// `routerProvider.overrideWithValue(buildRouter(initialLocation: '/calendar'))`.
final routerProvider = Provider<GoRouter>((ref) {
  final router = buildRouter();
  ref.onDispose(router.dispose);
  return router;
});
